INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-mother','mother','/ˈmʌðə/','noun','a female parent','母亲','Mother is another word for mum.','母亲是妈妈的正式说法。','[{"en":"My mother is a teacher.","zh":"我妈妈是一名老师。"},{"en":"Mother is cooking dinner.","zh":"母亲在做晚饭。"}]',NULL,'👩',1,'["core","family"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-mouth','mouth','/maʊθ/','noun','the part of your face you use to eat and speak','嘴','You eat and speak with your mouth.','你用嘴吃东西和说话。','[{"en":"Open your mouth.","zh":"张开嘴。"},{"en":"My mouth is small.","zh":"我的嘴很小。"}]',NULL,'👄',1,'["core","body"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-mum','mum','/mʌm/','noun','your mother','妈妈','Mum is another word for mother.','妈妈是母亲的另一种说法。','[{"en":"My mum is kind.","zh":"我妈妈很和蔼。"},{"en":"Mum makes good cake.","zh":"妈妈做的蛋糕很好吃。"}]',NULL,'👩',1,'["core","family"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-name','name','/neɪm/','noun','the word you are called by','名字','Your name is what people call you.','名字是别人对你的称呼。','[{"en":"My name is Tom.","zh":"我的名字是汤姆。"},{"en":"What is your name?","zh":"你叫什么名字？"}]',NULL,'🏷️',1,'["core","object"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-need','need','/niːd/','verb','to have to have something','需要','To need is to have to have something.','需要就是必须有某样东西。','[{"en":"I need a pencil.","zh":"我需要一支铅笔。"},{"en":"We need water to live.","zh":"我们需要水才能生存。"}]',NULL,'🙏',1,'["core","verb"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-new','new','/njuː/','adjective','not old','新的','New means not old.','新就是不是旧的。','[{"en":"I have a new bag.","zh":"我有一个新包。"},{"en":"This is a new book.","zh":"这是一本新书。"}]',NULL,'✨',1,'["core","adjective"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-nice','nice','/naɪs/','adjective','good and pleasant','好的；友好的','Nice means good and pleasant.','好就是不错、让人愉快。','[{"en":"She is a nice person.","zh":"她是一个好人。"},{"en":"The weather is nice today.","zh":"今天天气很好。"}]',NULL,'😊',1,'["core","adjective"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-nine','nine','/naɪn/','number','the number 9','九','Nine is the number after eight.','九是八后面的数字。','[{"en":"I have nine books.","zh":"我有九本书。"},{"en":"Nine children are playing.","zh":"九个孩子在玩耍。"}]',NULL,'9️⃣',1,'["core","number"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-O''clock','O''clock','/əˈklɒk/','adverb','used to say the exact hour','……点钟','O''clock means the exact hour.','点钟就是整点。','[{"en":"It is five o''clock.","zh":"现在五点了。"},{"en":"We eat at seven o''clock.","zh":"我们七点吃饭。"}]',NULL,'🕐',1,'["core","adverb"]',1793836800000,1793836800000,NULL);
