INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-red','red','/red/','adjective','the color of blood','红色的','Red is the color of an apple.','红色是苹果的颜色。','[{"en":"The apple is red.","zh":"苹果是红色的。"},{"en":"I have a red car.","zh":"我有一辆红色的车。"}]',NULL,'🔴',1,'["core","color"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-say','say','/seɪ/','verb','to speak words','说','To say is to speak words.','说就是用语言表达。','[{"en":"Say hello to your teacher.","zh":"跟老师问好。"},{"en":"What did you say?","zh":"你说什么？"}]',NULL,'💬',1,'["core","action"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-school','school','/skuːl/','noun','a place where children learn','学校','A school is a place where children learn.','学校是孩子们学习的地方。','[{"en":"I go to school every day.","zh":"我每天去上学。"},{"en":"Our school is big.","zh":"我们的学校很大。"}]',NULL,'🏫',1,'["core","place"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-seven','seven','/ˈsevn/','number','the number 7','七','Seven is the number after six.','七是六后面的数字。','[{"en":"There are seven days in a week.","zh":"一周有七天。"},{"en":"I have seven crayons.","zh":"我有七支蜡笔。"}]',NULL,'7️⃣',1,'["core","number"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-share','share','/ʃeə/','verb','to give part of something to someone else','分享','To share is to give part of something to someone else.','分享就是把东西分给别人一部分。','[{"en":"I share my toys with my sister.","zh":"我和妹妹分享我的玩具。"},{"en":"Let''s share the cake.","zh":"我们分蛋糕吃吧。"}]',NULL,'🤝',1,'["core","action"]',1793836800000,1793836800000,NULL);
