INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-smile','smile','/smaɪl/','noun','a happy look on your face','微笑','A smile is a happy look on your face.','微笑是你脸上开心的表情。','[{"en":"She has a big smile.","zh":"她笑得很灿烂。"},{"en":"Give me a smile.","zh":"给我一个微笑。"}]',NULL,'😊',1,'["core","emotional"]',1793836800000,1793836800000,NULL);
