INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-tall','tall','/tɔːl/','adjective','higher than average','高的','Tall means higher than average.','高就是比一般要高。','[{"en":"The tree is tall.","zh":"这棵树很高。"},{"en":"My brother is tall.","zh":"我哥哥很高。"}]',NULL,'📏',1,'["core","adjective"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-them','them','/ðem/','pronoun','the people or things you are talking about','他们（宾格）','Them is the word for those people or things.','他们是指你正在谈论的那些人或东西。','[{"en":"I see them.","zh":"我看到他们了。"},{"en":"Give the toys to them.","zh":"把玩具给他们。"}]',NULL,'👥',1,'["core","pronoun"]',1793836800000,1793836800000,NULL);
