INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-tiger','tiger','/ˈtaɪɡə/','noun','a big wild cat with orange and black stripes','老虎','A tiger is a big wild cat with stripes.','老虎是一种有条纹的大型野生猫科动物。','[{"en":"The tiger is orange and black.","zh":"老虎是橙色和黑色的。"},{"en":"Tigers are strong.","zh":"老虎很强壮。"}]',NULL,'🐯',1,'["core","animal"]',1793836800000,1793836800000,NULL);
