INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-us','us','/ʌs/','pronoun','you and me','我们（宾格）','Us means you and me together.','我们是指你和我一起。','[{"en":"Come with us.","zh":"跟我们一起来。"},{"en":"Look at us.","zh":"看我们。"}]',NULL,'👫',1,'["core","pronoun"]',1793836800000,1793836800000,NULL);
INSERT INTO "words" ("id","text","phonetic","part_of_speech","meaning_en","meaning_zh","definition_en","definition_zh","examples","image","emoji","level","tags","created_at","updated_at","archived_at") VALUES('w-water','water','/ˈwɔːtə/','noun','clear liquid that we drink','水','Water is a clear liquid we drink.','水是我们喝的透明液体。','[{"en":"I drink water.","zh":"我喝水。"},{"en":"The water is cold.","zh":"水很凉。"}]',NULL,'💧',1,'["core","food"]',1793836800000,1793836800000,NULL);
