PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `avatar_stages` (
	`avatar_id` text NOT NULL,
	`stage` text NOT NULL,
	`file` text NOT NULL,
	PRIMARY KEY(`avatar_id`, `stage`),
	FOREIGN KEY (`avatar_id`) REFERENCES `avatars`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `avatars` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`name_zh` text NOT NULL,
	`color` text NOT NULL,
	`pale` text NOT NULL,
	`sort_order` integer NOT NULL
);
CREATE TABLE `content_meta` (
	`id` integer PRIMARY KEY NOT NULL,
	`schema_version` integer NOT NULL,
	`dataset` text NOT NULL,
	`content_version` text NOT NULL,
	CONSTRAINT "content_meta_id" CHECK("content_meta"."id" = 1),
	CONSTRAINT "content_meta_dataset" CHECK("content_meta"."dataset" IN ('dev', 'final'))
);
CREATE TABLE `pack_words` (
	`pack_id` text NOT NULL,
	`word_id` text NOT NULL,
	`position` integer NOT NULL,
	PRIMARY KEY(`pack_id`, `position`),
	FOREIGN KEY (`pack_id`) REFERENCES `packs`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`word_id`) REFERENCES `words`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "pack_words_position" CHECK("pack_words"."position" >= 1)
);
CREATE TABLE `packs` (
	`id` text PRIMARY KEY NOT NULL,
	`topic_id` text NOT NULL,
	`title` text NOT NULL,
	`title_zh` text NOT NULL,
	`sort_order` integer NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	`archived_at` integer,
	FOREIGN KEY (`topic_id`) REFERENCES `topics`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `topics` (
	`id` text PRIMARY KEY NOT NULL,
	`title` text NOT NULL,
	`title_zh` text NOT NULL,
	`icon` text NOT NULL,
	`description` text NOT NULL,
	`description_zh` text NOT NULL,
	`sort_order` integer NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	`archived_at` integer
);
CREATE TABLE `words` (
	`id` text PRIMARY KEY NOT NULL,
	`text` text NOT NULL,
	`phonetic` text NOT NULL,
	`part_of_speech` text NOT NULL,
	`meaning_en` text NOT NULL,
	`meaning_zh` text NOT NULL,
	`definition_en` text NOT NULL,
	`definition_zh` text NOT NULL,
	`examples` text NOT NULL,
	`image` text,
	`emoji` text,
	`level` integer NOT NULL,
	`tags` text DEFAULT '[]' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	`archived_at` integer,
	CONSTRAINT "words_level" CHECK("words"."level" IN (1, 2, 3)),
	CONSTRAINT "words_examples_json" CHECK(json_valid("words"."examples")),
	CONSTRAINT "words_tags_json" CHECK(json_valid("words"."tags"))
);
CREATE TABLE `metric_events` (
	`user_id` text NOT NULL,
	`event_id` text NOT NULL,
	`name` text NOT NULL,
	`delta` real NOT NULL,
	`created_at` integer NOT NULL,
	PRIMARY KEY(`user_id`, `event_id`),
	FOREIGN KEY (`user_id`) REFERENCES `users`(`oid`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `metrics` (
	`user_id` text NOT NULL,
	`name` text NOT NULL,
	`value` real NOT NULL,
	`updated_at` integer NOT NULL,
	PRIMARY KEY(`user_id`, `name`),
	FOREIGN KEY (`user_id`) REFERENCES `users`(`oid`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `pack_introductions` (
	`user_id` text NOT NULL,
	`pack_id` text NOT NULL,
	`word_id` text NOT NULL,
	`introduced_at` integer NOT NULL,
	PRIMARY KEY(`user_id`, `pack_id`, `word_id`),
	FOREIGN KEY (`user_id`) REFERENCES `users`(`oid`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`pack_id`) REFERENCES `packs`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`word_id`) REFERENCES `words`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `profiles` (
	`user_id` text PRIMARY KEY NOT NULL,
	`character_name` text NOT NULL,
	`avatar` text NOT NULL,
	`current_topic_id` text,
	`xp` integer NOT NULL,
	`created_at` integer NOT NULL,
	`last_practice_at` integer NOT NULL,
	`last_wake_at` integer,
	`frozen_days` integer NOT NULL,
	`care_tokens` integer NOT NULL,
	`sessions_since_last_token` integer NOT NULL,
	`completed_sessions` integer NOT NULL,
	`streak_count` integer NOT NULL,
	`best_streak` integer NOT NULL,
	`last_streak_date` text,
	`last_monthly_review_at` integer,
	`locale` text NOT NULL,
	`role` text DEFAULT 'user' NOT NULL,
	`user_avatar_key` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`oid`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`current_topic_id`) REFERENCES `topics`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "profiles_locale" CHECK("profiles"."locale" IN ('en', 'zh')),
	CONSTRAINT "profiles_role" CHECK("profiles"."role" IN ('user', 'teacher', 'admin'))
);
CREATE TABLE `progress` (
	`user_id` text NOT NULL,
	`word_id` text NOT NULL,
	`status` text NOT NULL,
	`strength` real NOT NULL,
	`next_review_at` integer NOT NULL,
	`correct_count` integer NOT NULL,
	`wrong_count` integer NOT NULL,
	`first_seen_at` integer NOT NULL,
	`last_seen_at` integer NOT NULL,
	`mastery_xp_awarded` integer NOT NULL,
	PRIMARY KEY(`user_id`, `word_id`),
	FOREIGN KEY (`user_id`) REFERENCES `users`(`oid`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`word_id`) REFERENCES `words`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "progress_status" CHECK("progress"."status" IN ('new', 'learning', 'mastered')),
	CONSTRAINT "progress_strength" CHECK("progress"."strength" >= 0 AND "progress"."strength" <= 1)
);
CREATE TABLE `session_metrics` (
	`user_id` text NOT NULL,
	`session_id` text NOT NULL,
	`name` text NOT NULL,
	`delta` real NOT NULL,
	PRIMARY KEY(`user_id`, `session_id`, `name`),
	FOREIGN KEY (`user_id`,`session_id`) REFERENCES `sessions`(`user_id`,`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `sessions` (
	`id` text NOT NULL,
	`user_id` text NOT NULL,
	`kind` text NOT NULL,
	`local_date` text NOT NULL,
	`content_version` text NOT NULL,
	`xp_earned` integer NOT NULL,
	`finished_at` integer NOT NULL,
	`created_at` integer NOT NULL,
	PRIMARY KEY(`user_id`, `id`),
	FOREIGN KEY (`user_id`) REFERENCES `users`(`oid`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "sessions_kind" CHECK("sessions"."kind" IN ('daily', 'monthly'))
);
CREATE TABLE `users` (
	`oid` text PRIMARY KEY NOT NULL,
	`created_at` integer NOT NULL,
	`last_seen_at` integer NOT NULL,
	`email` text
);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX `pack_words_pack_word` ON `pack_words` (`pack_id`,`word_id`);
CREATE INDEX `pack_words_word` ON `pack_words` (`word_id`);
CREATE INDEX `packs_topic` ON `packs` (`topic_id`);
CREATE UNIQUE INDEX `words_text_nocase` ON `words` (`text` COLLATE NOCASE);
